package com.resicheck.connect.demo

import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import android.util.AtomicFile
import android.util.Base64
import org.json.JSONObject
import org.json.JSONArray
import java.util.UUID
import com.facebook.react.bridge.*
import java.io.File
import java.security.KeyStore
import java.util.concurrent.Executors
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/** Independent disposable cache. No session store, network, external storage or logs. */
class ConnectConversationCacheModule(context: ReactApplicationContext): ReactContextBaseJavaModule(context) {
 companion object { private val executor=Executors.newSingleThreadExecutor(); private const val ALIAS="com.resicheck.connect.conversation-cache.v1"; private const val MAX=12582912 }
 private val file=AtomicFile(File(context.noBackupFilesDir,"connect-conversation-cache-v1.bin"))
 private val aad="Connect|ibdlvlwdzmsrbqadrudb|received-cache|1".toByteArray(Charsets.UTF_8)
 override fun getName()="ConnectConversationCache"
 private fun key(create:Boolean):SecretKey? {val ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);val prior=ks.getKey(ALIAS,null) as? SecretKey;if(prior!=null||!create)return prior;val g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).build());return g.generateKey()}
 @ReactMethod fun read(p:Promise){executor.execute{var plain:ByteArray?=null;try{if(!file.baseFile.exists()){p.resolve(null);return@execute};if(file.baseFile.length()>MAX)throw IllegalStateException();val packed=file.readFully();if(packed.size<29)throw IllegalStateException();val c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(false)?:throw IllegalStateException(),GCMParameterSpec(128,packed.copyOfRange(0,12)));c.updateAAD(aad);val bytes=c.doFinal(packed.copyOfRange(12,packed.size));plain=bytes;p.resolve(String(bytes,Charsets.UTF_8))}catch(_:Throwable){file.delete();p.reject("CACHE_UNAVAILABLE","Não foi possível recuperar as cópias locais.")}finally{plain?.fill(0)}}}
 @ReactMethod fun write(value:String?,p:Promise){executor.execute{var bytes:ByteArray?=null;try{if(value==null){file.delete();val ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias(ALIAS))ks.deleteEntry(ALIAS);p.resolve(null);return@execute};val data=value.toByteArray(Charsets.UTF_8);bytes=data;if(data.size>MAX-28)throw IllegalArgumentException();val c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key(true));c.updateAAD(aad);val packed=c.iv+c.doFinal(data);val stream=file.startWrite();try{stream.write(packed);file.finishWrite(stream)}catch(e:Throwable){file.failWrite(stream);throw e};p.resolve(null)}catch(_:Throwable){p.reject("CACHE_UNAVAILABLE","Não foi possível atualizar as cópias locais.")}finally{bytes?.fill(0)}}}

 private val recordsRoot=File(context.noBackupFilesDir,"connect-received-cache-v2")
 private fun userDir(user:String):File {require(user.matches(Regex("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}")));recordsRoot.mkdirs();val dir=File(recordsRoot,user);dir.mkdirs();require(dir.canonicalFile.parentFile==recordsRoot.canonicalFile);return dir}
 private fun recordName(key:String):Boolean=key.length<=232&&key.matches(Regex("[pa]/[a-f0-9/-]+"))&&!key.contains("..")
 private fun accountKey(user:String,reset:Boolean=false):SecretKey {val alias=ALIAS+".v2."+user;val ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(reset&&ks.containsAlias(alias))ks.deleteEntry(alias);val old=ks.getKey(alias,null)as?SecretKey;if(old!=null)return old;val g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).build());return g.generateKey()}
 private fun recordAad(user:String,key:String)=("Connect|received-cache|2|"+user+"|"+key).toByteArray(Charsets.UTF_8)
 private fun encryptRecord(user:String,key:String,data:ByteArray):ByteArray {val c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,accountKey(user));c.updateAAD(recordAad(user,key));return c.iv+c.doFinal(data)}
 private fun decryptRecord(user:String,key:String,data:ByteArray):ByteArray {require(data.size in 29..(16777216+28));val c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,accountKey(user),GCMParameterSpec(128,data.copyOfRange(0,12)));c.updateAAD(recordAad(user,key));return c.doFinal(data.copyOfRange(12,data.size))}
 private fun writeRecord(file:File,bytes:ByteArray){val atomic=AtomicFile(file);val out=atomic.startWrite();try{out.write(bytes);atomic.finishWrite(out)}catch(e:Throwable){atomic.failWrite(out);throw e}}
 private fun initialState()=JSONObject().put("generation",UUID.randomUUID().toString()).put("automatic",false).put("limitMb",256).put("limitBytes",268435456).put("availableBytes",JSONObject.NULL).put("migrated",false).put("records",JSONArray())
 private fun loadRecords(user:String):JSONObject {val dir=userDir(user);val f=AtomicFile(File(dir,"index.bin"));if(!f.baseFile.exists()){val empty=initialState();saveRecords(user,empty);return empty};require(f.baseFile.length()<=4194304);val bytes=decryptRecord(user,"index",f.readFully());try{val s=JSONObject(String(bytes,Charsets.UTF_8));require(s.getJSONArray("records").length()<=10000);require(s.getString("generation").matches(Regex("[a-f0-9-]{36}")));return s}finally{bytes.fill(0)}}
 private fun saveRecords(user:String,state:JSONObject){val bytes=state.toString().toByteArray(Charsets.UTF_8);try{require(bytes.size<=4194304);writeRecord(File(userDir(user),"index.bin"),encryptRecord(user,"index",bytes))}finally{bytes.fill(0)}}
 private fun blobFile(dir:File,name:String):File {require(name.matches(Regex("[a-f0-9-]{36}\\.bin")));val f=File(dir,name);require(f.canonicalFile.parentFile==dir.canonicalFile);return f}
 private fun cleanOrphans(user:String,s:JSONObject){val keep=mutableSetOf<String>();val rows=s.getJSONArray("records");for(i in 0 until rows.length())keep.add(rows.getJSONObject(i).getString("file"));val dir=userDir(user);dir.listFiles()?.filter{it.name.matches(Regex("[a-f0-9-]{36}\\.bin"))&&!keep.contains(it.name)}?.forEach{require(it.canonicalFile.parentFile==dir.canonicalFile);it.delete()}}
 @ReactMethod fun recordsOpen(user:String,p:Promise){executor.execute{try{val s=loadRecords(user);cleanOrphans(user,s);val a=userDir(user).usableSpace;val rows=s.getJSONArray("records");var used=0L;for(i in 0 until rows.length())used+=rows.getJSONObject(i).getLong("bytes");s.put("availableBytes",a).put("limitBytes",minOf(s.getInt("limitMb").toLong()*1048576L,maxOf(0L,used+a-67108864L)));p.resolve(s.toString())}catch(_:Throwable){p.reject("CACHE_UNAVAILABLE","Não foi possível recuperar as cópias locais.")}}}
 @ReactMethod fun recordsGet(user:String,generation:String,key:String,p:Promise){executor.execute{var plain:ByteArray?=null;try{require(recordName(key));val s=loadRecords(user);require(s.getString("generation")==generation);val rows=s.getJSONArray("records");var meta:JSONObject?=null;for(i in 0 until rows.length())if(rows.getJSONObject(i).getString("key")==key)meta=rows.getJSONObject(i);if(meta==null){p.resolve(null);return@execute};val f=blobFile(userDir(user),meta.getString("file"));require(f.length()<=16777216+28);val b=decryptRecord(user,key,f.readBytes());plain=b;require(b.size==meta.getInt("bytes"));meta.put("at",System.currentTimeMillis());saveRecords(user,s);p.resolve(Base64.encodeToString(b,Base64.NO_WRAP))}catch(_:Throwable){p.reject("CACHE_UNAVAILABLE","Não foi possível recuperar as cópias locais.")}finally{plain?.fill(0)}}}
 @ReactMethod fun recordsApply(user:String,generation:String,change:String,p:Promise){executor.execute{var bytes:ByteArray?=null;try{require(change.length<=23000000);val c=JSONObject(change);val old=loadRecords(user);require(old.getString("generation")==generation||c.optBoolean("clear")||c.optBoolean("logout"));val dir=userDir(user);val rows=mutableListOf<JSONObject>();val before=old.getJSONArray("records");var used=0L;for(i in 0 until before.length()){val r=before.getJSONObject(i);used+=r.getLong("bytes");rows.add(r)}
 val clear=c.optBoolean("clear")||c.optBoolean("logout");val prefix=if(c.has("removePrefix"))c.getString("removePrefix")else null;if(prefix!=null)require(recordName(prefix));if(clear)rows.clear();if(prefix!=null)rows.removeAll{it.getString("key").startsWith(prefix)}
 val limitMb=if(c.optBoolean("logout"))256 else c.optInt("limitMb",old.getInt("limitMb"));require(limitMb in listOf(64,256,1024));val available=dir.usableSpace;val limit=minOf(limitMb.toLong()*1048576L,maxOf(0L,used+available-67108864L));val put=if(c.has("put"))c.getJSONObject("put")else null;var name:String?=null
 if(put!=null){val k=put.getString("key");require(recordName(k));val kind=put.getString("kind");require(kind=="page"||kind=="audio");val raw=put.getString("base64");require(raw.length<=22369624);bytes=Base64.decode(raw,Base64.NO_WRAP);require(bytes.size in 1..16777216);rows.removeAll{it.getString("key")==k};name=UUID.randomUUID().toString()+".bin";rows.add(JSONObject().put("key",k).put("kind",kind).put("bytes",bytes.size).put("at",System.currentTimeMillis()).put("file",name))}
 rows.sortWith(compareBy<JSONObject>{it.getLong("at")}.thenBy{it.getString("key")});var total=rows.sumOf{it.getLong("bytes")};while(rows.isNotEmpty()&&(total>limit||rows.size>10000)){total-=rows.removeAt(0).getLong("bytes")}
 if(clear)accountKey(user,true);if(put!=null&&rows.any{it.getString("file")==name})writeRecord(blobFile(dir,name!!),encryptRecord(user,put.getString("key"),bytes!!));val result=JSONObject(old.toString()).put("records",JSONArray(rows)).put("limitMb",limitMb).put("limitBytes",limit).put("availableBytes",available).put("automatic",if(c.optBoolean("logout"))false else c.optBoolean("automatic",old.getBoolean("automatic"))).put("migrated",clear||c.optBoolean("migrated",old.optBoolean("migrated")))
 if(clear||prefix!=null)result.put("generation",UUID.randomUUID().toString());saveRecords(user,result);cleanOrphans(user,result);p.resolve(result.toString())
 }catch(_:Throwable){p.reject("CACHE_UNAVAILABLE","Não foi possível atualizar as cópias locais.")}finally{bytes?.fill(0)}}}
}
